contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Renounce ownership so owner() should return address(0)
        c.renounceOwnership();
        // Try to call a onlyOwner function; it should succeed if owner() returns address(0) (reference)
        // but revert if owner() returns address(0xdead) (bug)
        try c.setOperator(address(this)) {
            // If we get here, the call succeeded meaning owner() returned address(0) => reference
