pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Renounce ownership: reference sets owner to address(0), buggy version's owner() returns 0xdead regardless
        c.renounceOwnership();

        // Try to call onlyOwner function setOperator as the deployer (this contract)
        bool ok;
        try c.setOperator(address(0x1234)) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: owner() returns 0, so this contract is not owner, but the modifier checks msg.sender == owner()
        // Actually after renounceOwnership on reference, owner() returns address(0), so caller (this contract) != owner, revert.
        // Wait – both should revert? Let's re-analyze: 
        // The change is only in owner() return value. In reference, owner() returns 0 after renounceOwnership.
        // In mutant, owner() always returns 0xdead.
        // onlyOwner checks msg.sender == owner(). 
        // For reference: owner()=0, msg.sender=this, so false → revert.
        // For mutant: owner()=0xdead, msg.sender=this, so false → revert.
        // Both revert? That wouldn't differentiate.
        // Let's pick a scenario where the difference actually matters.
        // Actually, the only way owner() difference matters is if the caller IS the owner address in reference but not in mutant.
        // If we set operator address to be the same as the deployer's address? No.
        // Better: use a different entry that uses owner() differently.
        // The onlyOperatorOrOwner modifier: allows if msg.sender == operator OR msg.sender == owner().
        // So if we call withdrawAndUnwrap as a third party (neither operator nor owner), in reference after renounceOwnership owner()=0, so msg.sender != 0 and != operator → revert.
        // In mutant owner()=0xdead, same situation → revert. Not different.
        // Wait, what if we call as the deployer himself? Operator might be someone else. 
        // Let's set operator to zero address. Then in reference, after renounceOwnership, onlyOperatorOrOwner allows owner()=0 → zero address is msg.sender? No.
        // I'm overcomplicating. The simplest is: owner() getter returns different values.
        bool isOwnerMatch = (c.owner() == address(this));
        // In reference after renounceOwnership: owner()=0, so condition false.
        // In mutant: owner()=0xdead, so condition also false? Actually this contract is address(this) = deployed test contract address, not 0xdead. So both false?
        // The difference: reference owner()=0, mutant owner()=0xdead. We can assert c.owner() == address(0) (reference true, mutant false). That's observable!
        // So just check the return of owner() directly.
        assertTrue(c.owner() == address(0), "owner should be zero after renounceOwnership");
    }
}

