pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { 
        c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); 
    }
    function testRegression_property() public {
        // Set operator to a different address (0x123) so that onlyOperatorOrOwner checks both operator and owner
        c.setOperator(address(0x123));
        // Set a rewards address so withdrawAndUnwrap can be called (it calls IBaseRewardPool)
        // But we don't need actual rewards pool; we just need the call to fail/succeed based on modifier
        // To avoid revert in IBaseRewardPool, we mock it via vm.mockCall? No, cheatcodes forbidden.
        // Instead, we use an empty address for rewards and catch the revert from the inner call (expected).
        // The bug manifests in the modifier check before any inner call.
        // So we call withdrawAndUnwrap with minimal amount, and catch the revert.
        bool ok = false;
        try c.withdrawAndUnwrap(0, false, address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, owner() returns this contract (setUp caller), msg.sender = address(this) != operator (0x123) but == owner() so onlyOperatorOrOwner passes -> inner call reverts due to zero address rewards pool -> catch sets ok = false. Wait, we need the assertion to show divergence: reference returns true (modifier passes) and bug returns false (modifier fails). But both catch because inner call reverts. We need a scenario where the modifier check itself causes a different revert behavior.
        // Actually, the modifier onlyOperatorOrOwner checks msg.sender != operator && msg.sender != owner(). In reference, owner() = address(this) so msg.sender == owner() passes. In mutant, owner() = address(0), so msg.sender != owner() is true, and since msg.sender != operator also true, it reverts with NotOperatorOrOwner. So in reference, the call goes through to the inner code and reverts with a different error; in mutant, it reverts with NotOperatorOrOwner. We can catch both and check the revert message? But we are only allowed assertTrue, not vm.expectRevert. So we need a case where reference succeeds and mutant reverts. For that, we need to avoid the inner revert. We can set rewardsRecipient to address(this) and then pass a rewards pool that does not revert? But we cannot mock. Instead, we can add a try-catch on the modifier check by calling a function that only does modifier check.
        // Actually, withdrawAndUnwrap does a call to clpToken.balanceOf and then conditionally calls IBaseRewardPool. If we set clpToken to a token that returns 0 balance, and amount=0, then toUnstake=0, and to=address(0) so no transfer. The only thing left is the modifier check. If toUnstake=0 and to=address(0), the call should succeed (no transfers, no external calls). In reference: modifier passes -> function executes successfully. In mutant: modifier fails -> revert. So we can set clpToken to a mock token that returns balance 0.
        // Deploy a simple ERC20 mock returning 0 balance
        MockERC20 token = new MockERC20();
        c = new C(address(0x123), IERC20(address(token)), ICVXBooster(address(0)), new address[](0));
        c.setRewardsRecipient(address(0x456)); // any
        // Now call withdrawAndUnwrap(0, false, address(0)) as owner (this contract)
        bool ok = false;
        try c.withdrawAndUnwrap(0, false, address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, owner() returns address(this) -> modifier passes -> ok = true
        // In mutant, owner() returns address(0) -> modifier fails -> ok = false
        assertTrue(ok == true); // This assertion passes on reference (ok true) and fails on mutant (ok false)
    }
}

contract MockERC20 is IERC20 {
    function totalSupply() external view returns (uint256) { return 0; }
    function balanceOf(address) external view returns (uint256) { return 0; }
    function transfer(address, uint256) external returns (bool) { return true; }
    function allowance(address, address) external view returns (uint256) { return 0; }
    function approve(address, uint256) external returns (bool) { return true; }
    function transferFrom(address, address, uint256) external returns (bool) { return true; }
}

