pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        address operatorBefore = c.operator();

        // Bug: transfer ownership to zero address succeeds in buggy version, fails in reference
        // The owner (this contract) tries to transfer ownership to address(0)
        // Reference requires newOwner != address(0) so it reverts
        // Buggy version allows it

        // Use try/catch to handle the potential revert from reference
        bool transferSucceeded = false;
        try c.transferOwnership(address(0)) {
            transferSucceeded = true;
        } catch {
            transferSucceeded = false;
        }

        // If transfer succeeded (buggy version), then onlyOwner functions work with new owner
        // If transfer failed (reference), onlyOwner functions still work with original owner

        if (transferSucceeded) {
            // Buggy version: owner is now address(0), so onlyOwner functions can't be called
            // by anyone except the zero address (impossible)
            // So setOperator should revert
            address newOperator = address(0x1234);
            bool setOpReverted = false;
            try c.setOperator(newOperator) {
                setOpReverted = false;
            } catch {
                setOpReverted = true;
            }
            assertTrue(setOpReverted, "Buggy: setOperator should revert because owner is zero");
        } else {
            // Reference: ownership transfer failed, owner unchanged
            // Owner can still call setOperator
            address newOperator = address(0x1234);
            c.setOperator(newOperator);
            assertTrue(c.operator() == newOperator, "Reference: operator should be updated");
        }
    }
}

